module.exports=[58407,a=>{"use strict";let b=["En [Mi espacio] cada empleado descarga sus boletas y solicita vacaciones sin pasar por Recursos Humanos.","El reporte [Planilla IHSS] sale con las mismas cifras que se descontaron en la planilla: usa el mismo cálculo.","Una planilla aprobada no se edita: se anula y se vuelve a calcular. Las cuotas de préstamos se devuelven solas.","El almuerzo no cuenta como tiempo de trabajo: si nadie lo marca, se descuentan 60 minutos de la jornada.","En [Parámetros de ley] conviene revisar cada enero el techo del IHSS y la tabla progresiva del ISR.","Las horas extra se liquidan según la franja: 125 % diurna, 175 % nocturna y 200 % en feriado o día de descanso.","Desde [Reportes] la nómina para banco toma sólo planillas aprobadas o pagadas."];a.s(["p",0,{"2.0.3":[{titulo:"Buscar al empleado escribiendo",detalle:"En documentos, dotaciones, marcajes, incapacidades, evaluaciones, deducciones, liquidaciones y demás: nombre en cualquier orden o código, en vez de una lista larga.",modulo:"General"},{titulo:"Planillas por período",detalle:"Generar el período de todas las sucursales, revisar, confirmar, aprobar y pagar varias a la vez, imprimir el período completo y ver qué falta en un tablero.",modulo:"Nómina"},{titulo:"Formato por grupo",detalle:"En Deducciones → Exportar: todo un grupo en un Excel, con una hoja quincenal y una mensual y las sucursales una debajo de otra. Se importa entero.",modulo:"Deducciones"},{titulo:"Horas extra en el formato",detalle:"El formato de captura puede llevar las horas extra del 25, 50, 75 y 100 % antes de las deducciones.",modulo:"Deducciones"},{titulo:"Comprobantes de varias planillas",detalle:"Por correo o impresos en un solo PDF. Cada deducción con su nombre, como en la planilla, y el sueldo mensual bajo la identidad.",modulo:"Nómina"},{titulo:"La planilla en su orden",detalle:"Ordenada por antigüedad u otro campo, y las columnas de deducción en el orden de la empresa, igual en pantalla e impresa.",modulo:"Nómina"},{titulo:"Respaldos más seguros",detalle:"También a un disco USB, conservan diarios, semanales y mensuales, avisan por correo si fallan y cada domingo se prueba que se pueden restaurar.",modulo:"Configuración"},{titulo:"Relojes Hikvision",detalle:"Probar la conexión con el reloj por la red y traer sus marcas.",modulo:"Asistencia"}],"2.0.2":[{titulo:"Formato de captura por sucursal",detalle:"En Deducciones → Exportar: los empleados por departamento, como su planilla, con subtotales, para escribir los montos a mano y volver a importarlos.",modulo:"Deducciones"},{titulo:"Su planilla, tal como viene",detalle:"Montos del período lee encabezados en dos filas, abreviaturas como «Ptamo.» o «Coop.», guiones y totales, y recuerda a qué tipo va cada columna.",modulo:"Deducciones"},{titulo:"ISR automático o manual",detalle:"En Parámetros de ley. En manual se retiene el ISR que se importa para cada quincena: útil al empezar a mitad de año.",modulo:"Nómina"},{titulo:"Limpiar pruebas",detalle:"En Configuración → Sistema: quita las planillas de prueba sin aprobar y los montos importados desde una fecha, y devuelve las cuotas que cobraron.",modulo:"Configuración"},{titulo:"En el celular y la tablet",detalle:"Menú, tablas y formularios hechos para el dedo, y se puede agregar a la pantalla de inicio como una aplicación.",modulo:"General"},{titulo:"Conectar celulares al servidor",detalle:"La página del certificado trae un código QR y los pasos para Android y iPhone.",modulo:"Instalación"}],"2.0.1":[{titulo:"Columnas a su medida",detalle:"En Empleados, «Columnas» elige qué datos se ven: identidad, jefe directo, frecuencia, antigüedad, banco, correo y más. Se recuerda en cada navegador.",modulo:"Empleados"},{titulo:"Exportar estructura",detalle:"Grupos, sucursales y departamentos con sus totales, hasta los puestos o cada empleado, en Excel o PDF. También en Reportes y en Jerarquía de nómina.",modulo:"Empleados"},{titulo:"Filtros de sucursal y estado",detalle:"La lista de empleados se filtra también por sucursal y por estado, con «Sin los dados de baja».",modulo:"Empleados"},{titulo:"Dónde trabaja, en la ficha",detalle:"Arriba de la ficha van juntos el grupo, la sucursal y el departamento.",modulo:"Empleados"},{titulo:"Guardar y registrar otro, también al editar",detalle:"Guarda los cambios de un empleado y abre el alta del siguiente.",modulo:"Empleados"},{titulo:"Configuración en un menú",detalle:"Organización, Parametrizaciones, Integraciones y Sistema en un menú lateral, con la opción «Sólo íconos» para pantallas pequeñas.",modulo:"Configuración"},{titulo:"Foto del empleado",detalle:"Con la cámara del equipo o desde un archivo, en el alta y en Editar.",modulo:"Empleados"},{titulo:"Descuentos por asistencia",detalle:"Ausencias, séptimo día y permisos sin goce, y llegadas tarde si se encienden, en Configuración → Asistencia.",modulo:"Asistencia"},{titulo:"Identidades y cuentas en Excel",detalle:"Los reportes ya no le quitan el cero inicial a la identidad, al RTN ni a las cuentas bancarias.",modulo:"Reportes"}],"2.0":[{titulo:"Tablero ejecutivo",detalle:"Fuerza laboral, rotación, puntualidad, ausentismo, horas extra, costo de nómina frente al período anterior, pasivo laboral y décimos menos adelantos por sucursal, con filtros y exportación a Excel y PDF.",modulo:"Reportes"},{titulo:"Traslados entre sucursales",detalle:"El plan de horarios trae personal de otra sucursal por unos días sin cambiar su planilla, y se puede cargar desde Excel: una fila por empleado y día.",modulo:"Horarios"},{titulo:"Adelantos de décimos y negociación",detalle:"Registre adelantos del 13.º y 14.º, que se restan al pagar el décimo, y la negociación de prestaciones, que se resta de la cesantía al liquidar.",modulo:"Prestaciones"},{titulo:"Carga rápida de horas",detalle:"Horas ordinarias y extra de muchas personas en una cuadrícula que se llena con el teclado, o desde Excel con el DNI o el código.",modulo:"Asistencia"},{titulo:"Material de capacitación",detalle:"Manuales, videos y documentos en cada capacitación, que el personal ve en Mi espacio sin poder descargarlos.",modulo:"Talento"},{titulo:"Evaluaciones por aspectos",detalle:"La calificación final es el promedio ponderado de los aspectos evaluados, que se configuran en general o por puesto.",modulo:"Talento"},{titulo:"Respaldos automáticos",detalle:"Respalde la base y los adjuntos a mano o cada día, en un disco, una carpeta de red o la nube (S3), cifrados con contraseña. En Configuración → Respaldos.",modulo:"Configuración"},{titulo:"RAP a mes vencido",detalle:"El RAP y la Reserva Laboral pueden calcularse sobre lo devengado el mes anterior, con la base importable en la plantilla, y la liquidación cobra lo pendiente del mes de salida.",modulo:"Nómina"},{titulo:"Salario promedio de la liquidación",detalle:"Se promedia por mes devengado: en planilla quincenal, dos quincenas son un mes. Antes salía a la mitad.",modulo:"Prestaciones"},{titulo:"Cierre por inactividad",detalle:"Tras unos minutos sin uso la sesión se cierra y hay que volver a ingresar. El tiempo se ajusta en Configuración → Seguridad.",modulo:"Seguridad"},{titulo:"Departamentos en todas las empresas",detalle:"Al crear un departamento, elija una empresa, todas o las que marque, en un grupo o en todos.",modulo:"Configuración"},{titulo:"Deducciones por período",detalle:"Exporte a Excel lo que se descuenta a cada empleado en la quincena, corríjalo y vuelva a importarlo: cooperativas y préstamos que cambian cada quincena.",modulo:"Deducciones"},{titulo:"Asignar a varios",detalle:"Una deducción a muchos empleados a la vez, con monto igual para todos o uno por persona.",modulo:"Deducciones"},{titulo:"Aportes en una o dos quincenas",detalle:"IHSS, RAP e impuesto vecinal divididos entre las dos quincenas o completos en una sola.",modulo:"Configuración"},{titulo:"Planilla detallada",detalle:"Días trabajados, total devengado, total deducciones y neto a pagar, con el resumen en la última página y papel legal o doble carta.",modulo:"Reportes"},{titulo:"Jerarquía de nómina",detalle:"Vista en árbol por frecuencia, grupo, empresa y departamento. Se activa en Configuración.",modulo:"Nómina"},{titulo:"Impresión por empresa",detalle:"Cada empresa en su hoja, con su nombre y RTN, en PDF o en Excel.",modulo:"Reportes"},{titulo:"Revisar antes de confirmar",detalle:"Compare la planilla con la anterior antes de confirmarla o aprobarla.",modulo:"Nómina"},{titulo:"Reabrir y anular planillas",detalle:"Una planilla aprobada o pagada se puede revertir, con motivo obligatorio y según los permisos de cada cuenta.",modulo:"Nómina"},{titulo:"Logo por sucursal",detalle:"Cada sucursal lleva su logo en sus comprobantes y documentos.",modulo:"Configuración"},{titulo:"Buscador general",detalle:"Encuentre empleados, planillas y pantallas con Ctrl K.",modulo:"Inicio"}],"1.0":[{titulo:"Planilla en borrador",detalle:"Revísela con sus reportes y recalcúlela las veces que haga falta. Las cuotas se cobran al confirmarla.",modulo:"Nómina"},{titulo:"Plantillas en Excel",detalle:"Empleados, deducciones y horas extra se cargan desde Excel, con instrucciones incluidas.",modulo:"Importar"},{titulo:"Cada división en su hoja",detalle:"Imprima la nómina con cada división en hoja aparte, en PDF o en Excel.",modulo:"Reportes"},{titulo:"Fondo de Reserva Laboral",detalle:"Aporte patronal del 4 % (Decreto 47-2024) en la planilla, el costo patronal y la partida contable.",modulo:"Nómina"},{titulo:"Parámetros de ley configurables",detalle:"IHSS, IVM, RAP, INFOP, la tabla de ISR y el impuesto vecinal se editan desde Configuración.",modulo:"Configuración"},{titulo:"Comprobantes por correo",detalle:"Cada boleta se envía al correo del empleado desde la planilla, con el servidor de correo configurable.",modulo:"Nómina"}]},"R",0,{whatsapp:"+504 9891-3809",whatsappUrl:"https://wa.me/50498913809",correo:"info@esc-systemhn.com"},"k",0,"2.0.3","r",0,function(a){let b=a.getMonth(),c=[];return(4===b||5===b)&&c.push({tono:5===b?"alerta":"aviso",texto:"Décimo cuarto mes: se paga en junio (Decreto 135-94). Devenga de julio a junio."}),(10===b||11===b)&&c.push({tono:11===b?"alerta":"aviso",texto:"Décimo tercer mes (aguinaldo): se paga en diciembre (Decreto 112-82). Devenga de enero a diciembre."}),0===b&&c.push({tono:"aviso",texto:"Nuevo año: verifique en Parámetros de ley el techo del IHSS y la tabla de ISR vigentes."}),c},"H",0,function(a){let c=Date.UTC(a.getUTCFullYear(),0,1);return b[Math.floor((a.getTime()-c)/864e5)%b.length]}])}];

